{#- Helpers for objectified DSW document context replies (metamodel 18.0). -#}
{% macro val(replies, path) -%}
{%- set r = replies.get(path|reply_path) if replies is defined and replies is not none else none -%}
{%- if r is not none and r.value is defined and r.value is not none -%}{{ r.value|safe }}{%- endif -%}
{%- endmacro %}

{% macro answer_label(entities, reply_uuid) -%}
{%- set a = entities.answers.get(reply_uuid) if entities and entities.answers is defined and reply_uuid else none -%}
{{- (a.label|safe) if a and a.label is defined else '' -}}
{%- endmacro %}

{% macro item_label(entities, choice_uuid) -%}
{%- set c = entities.choices.get(choice_uuid) if entities and entities.choices is defined and choice_uuid else none -%}
{{- (c.label|safe) if c and c.label is defined else '' -}}
{%- endmacro %}

{# Canonical resolvable identifier links. #}
{% macro doi_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set v=v|replace('https://dx.doi.org/','')|replace('http://dx.doi.org/','')|replace('https://doi.org/','')|replace('http://doi.org/','') -%}
{%- if v|lower is string and v|lower|truncate(4, true, '') == 'doi:' -%}{%- set v=v[4:]|trim -%}{%- endif -%}
{%- if v -%}https://doi.org/{{ v }}{%- endif -%}
{%- endmacro %}

{% macro orcid_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set v=v|replace('https://orcid.org/','')|replace('http://orcid.org/','') -%}
{%- if v -%}https://orcid.org/{{ v }}{%- endif -%}
{%- endmacro %}

{% macro ror_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set v=v|replace('https://ror.org/','')|replace('http://ror.org/','') -%}
{%- if v -%}https://ror.org/{{ v }}{%- endif -%}
{%- endmacro %}

{% macro spdx_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- if '/licenses/' in v -%}{%- set v=v.split('/licenses/',1)[1] -%}{%- endif -%}
{%- set v=v|replace('.html','')|trim('/') -%}
{%- if v -%}https://spdx.org/licenses/{{ v }}{%- endif -%}
{%- endmacro %}

{% macro edam_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- if v.startswith('http://') or v.startswith('https://') -%}{{ v }}
{%- elif v.startswith('EDAM:') -%}http://edamontology.org/{{ v[5:] }}
{%- elif v.startswith('format_') or v.startswith('operation_') or v.startswith('topic_') or v.startswith('data_') -%}http://edamontology.org/{{ v }}
{%- elif v -%}{{ v }}
{%- endif -%}
{%- endmacro %}

{% macro swh_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- if v.startswith('http://') or v.startswith('https://') -%}{{ v }}
{%- elif v.startswith('swh:') -%}https://archive.softwareheritage.org/{{ v }}/
{%- elif v -%}{{ v }}
{%- endif -%}
{%- endmacro %}

{% macro pmid_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set v=v|replace('https://pubmed.ncbi.nlm.nih.gov/','')|trim('/') -%}
{%- if v -%}https://pubmed.ncbi.nlm.nih.gov/{{ v }}/{%- endif -%}
{%- endmacro %}

{% macro pmcid_url(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set v=v|replace('https://www.ncbi.nlm.nih.gov/pmc/articles/','')|replace('https://pmc.ncbi.nlm.nih.gov/articles/','')|trim('/') -%}
{%- if v -%}https://pmc.ncbi.nlm.nih.gov/articles/{{ v }}/{%- endif -%}
{%- endmacro %}

{% macro known_link(value) -%}
{%- set v=value|default('',true)|trim -%}
{%- set low=v|lower -%}
{%- if not v -%}
{%- elif low.startswith('10.') or 'doi.org/' in low -%}{{ doi_url(v) }}
{%- elif low.startswith('swh:') or 'softwareheritage.org/' in low -%}{{ swh_url(v) }}
{%- elif 'ror.org/' in low -%}{{ ror_url(v) }}
{%- elif 'orcid.org/' in low -%}{{ orcid_url(v) }}
{%- elif v.startswith('EDAM:') or 'edamontology.org/' in low -%}{{ edam_url(v) }}
{%- else -%}{{ v }}
{%- endif -%}
{%- endmacro %}

