{# cost/access enum normalization #}
{% macro apply(ns, dc, entities, replies) -%}
{%- set cost=h.val(replies,[id.ch_lic,id.q_cost])|trim -%}{%- set costl=h.answer_label(entities,cost)|trim -%}
