{% import "src/_refs.j2" as id %}
{% import "src/_helpers.j2" as h %}
{# contributors, affiliations, ROR enrichment, synthesized funding PIs #}
{% macro apply(ns, dc, entities, replies) -%}
{# ---------------- Contributors and organizations ---------------- #}
{%- set cr=replies.get(([id.ch_general,id.q_contributors])|reply_path) -%}
{%- set citems=cr.value if cr is not none else [] -%}
{%- set cns=namespace(items=[],has_author=false,names=[],emails=[]) -%}
{%- for it in citems -%}
  {%- set given=h.val(replies,[id.ch_general,id.q_contributors,it,id.q_c_given])|trim -%}
  {%- set family=h.val(replies,[id.ch_general,id.q_contributors,it,id.q_c_family])|trim -%}
  {%- set name=(given ~ ' ' ~ family)|trim -%}
  {%- set email=h.val(replies,[id.ch_general,id.q_contributors,it,id.q_c_email])|trim -%}
  {%- set orcid=h.val(replies,[id.ch_general,id.q_contributors,it,id.q_c_orcid])|trim -%}
  {%- set url=h.val(replies,[id.ch_general,id.q_contributors,it,id.q_c_url])|trim -%}
  {%- set rr=replies.get(([id.ch_general,id.q_contributors,it,id.q_c_roles])|reply_path) -%}
  {%- set ritems=rr.value if rr is not none else [] -%}
  {%- set rns=namespace(roles=[]) -%}
  {%- for cu in ritems -%}
    {%- set lbl=h.item_label(entities,cu)|trim -%}
    {%- if lbl in ['Original author','Co-author','Maintainer','Successor','Principal investigator'] -%}
      {%- set rns.roles=rns.roles+[lbl] -%}
      {%- if lbl in ['Original author','Co-author'] %}{%- set cns.has_author=true -%}{%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- set p={} -%}
  {%- if name and rns.roles -%}
    {%- set p=dict(p,name=name,roles=rns.roles) -%}
    {%- if given %}{%- set p=dict(p,given_names=given) -%}{%- endif -%}
    {%- if family %}{%- set p=dict(p,family_names=family) -%}{%- endif -%}
    {%- if email %}{%- set p=dict(p,email=email) -%}{%- endif -%}
    {%- if orcid %}{%- set p=dict(p,orcid=h.orcid_url(orcid)|trim) -%}{%- endif -%}
    {%- if url %}{%- set p=dict(p,url=url) -%}{%- endif -%}
    {%- set ar=replies.get(([id.ch_general,id.q_contributors,it,id.q_c_affs])|reply_path) -%}
    {%- set aitems=ar.value if ar is not none else [] -%}
    {%- set ans=namespace(items=[]) -%}
    {%- for ait in aitems -%}
      {%- set sr=replies.get(([id.ch_general,id.q_contributors,it,id.q_c_affs,ait,id.q_c_aff])|reply_path) -%}
      {%- set orgit=sr.value|default('',true)|trim if sr is not none else '' -%}
      {%- if orgit -%}
        {%- set on=h.val(replies,[id.ch_general,id.q_orgs,orgit,id.q_org_name])|trim -%}
        {%- set oe=h.val(replies,[id.ch_general,id.q_orgs,orgit,id.q_org_email])|trim -%}
        {%- set ou=h.val(replies,[id.ch_general,id.q_orgs,orgit,id.q_org_url])|trim -%}
        {%- set oa=h.val(replies,[id.ch_general,id.q_orgs,orgit,id.q_org_addr])|trim -%}
        {%- set ror_r=replies.get(([id.ch_general,id.q_orgs,orgit,id.q_org_ror])|reply_path) -%}
        {%- set ror_raw=ror_r.raw if ror_r is not none and ror_r.raw is defined else none -%}
        {%- set oid0=ror_raw.id if ror_raw is mapping and ror_raw.id is defined else (ror_r.value|default('',true)|trim if ror_r is not none else '') -%}
        {%- set oid=h.ror_url(oid0)|trim if oid0 else '' -%}
        {%- if not on and ror_raw is mapping and ror_raw.names is defined -%}
          {%- for nm in ror_raw.names if not on -%}{%- if nm.value is defined and ('ror_display' in nm.types|default([]) or 'label' in nm.types|default([])) %}{%- set on=nm.value -%}{%- endif -%}{%- endfor -%}
        {%- endif -%}
        {%- if on -%}
          {%- set o={'name':on} -%}
          {%- if oid %}{%- set o=dict(o,identifier=oid) -%}{%- endif -%}
          {%- if oe %}{%- set o=dict(o,email=oe) -%}{%- endif -%}
          {%- if ou %}{%- set o=dict(o,url=ou) -%}{%- endif -%}
          {%- if oa %}{%- set o=dict(o,address=oa) -%}{%- endif -%}
          {%- set ans.items=ans.items+[o] -%}
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
    {%- if ans.items %}{%- set p=dict(p,affiliations=ans.items) -%}{%- endif -%}
    {%- set cns.items=cns.items+[p] -%}
    {%- set cns.names=cns.names+[name|lower] -%}
    {%- if email %}{%- set cns.emails=cns.emails+[email|lower] -%}{%- endif -%}
  {%- endif -%}
{%- endfor -%}

{# synthesize funding PIs, preserving free-text affiliation as organization{name} #}
{%- set fg=h.val(replies,[id.ch_general,id.q_funding])|trim -%}
{%- if h.answer_label(entities,fg)|trim == 'Yes' -%}
  {%- set fr=replies.get(([id.ch_general,id.q_funding,fg,id.q_funds])|reply_path) -%}
  {%- set fitems=fr.value if fr is not none else [] -%}
  {%- for fit in fitems -%}
    {%- set pir=replies.get(([id.ch_general,id.q_funding,fg,id.q_funds,fit,id.q_pis])|reply_path) -%}
    {%- set piitems=pir.value if pir is not none else [] -%}
    {%- for pit in piitems -%}
      {%- set pn=h.val(replies,[id.ch_general,id.q_funding,fg,id.q_funds,fit,id.q_pis,pit,id.q_pi_name])|trim -%}
      {%- set pe=h.val(replies,[id.ch_general,id.q_funding,fg,id.q_funds,fit,id.q_pis,pit,id.q_pi_email])|trim -%}
      {%- set pa=h.val(replies,[id.ch_general,id.q_funding,fg,id.q_funds,fit,id.q_pis,pit,id.q_pi_aff])|trim -%}
      {%- if pn and ((pe and pe|lower not in cns.emails) or (not pe and pn|lower not in cns.names)) -%}
        {%- set pp={'name':pn,'roles':['Principal investigator']} -%}
        {%- if pe %}{%- set pp=dict(pp,email=pe) -%}{%- endif -%}
        {%- if pa %}{%- set pp=dict(pp,affiliations=[{'name':pa}]) -%}{%- endif -%}
        {%- set cns.items=cns.items+[pp] -%}
        {%- set cns.names=cns.names+[pn|lower] -%}
        {%- if pe %}{%- set cns.emails=cns.emails+[pe|lower] -%}{%- endif -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
{%- endif -%}
{%- if cns.items and cns.has_author %}{%- set ns.root=dict(ns.root,contributors={'entries':cns.items}) -%}{%- endif -%}
{%- endmacro %}

