{%- endif -%}

{%- set st = namespace(value='') -%}

{# Prefer UUIDs because they are stable inside this KM; title matching is a fallback. #}
{%- if phase_uuid == 'a664ce2c-83b0-411a-bdf5-4f829a4ecc25' or phase_title == 'ideation' -%}
  {%- set st.value='concept' -%}

{%- elif phase_uuid == 'de478e18-2a3e-4349-804c-f1d8974897b1' or phase_title == 'planning' -%}
