{%- elif phase_uuid == 'fd08c186-34f3-4104-8715-702e8623393c' or phase_title == 'active development' -%}
  {%- set st.value='active' -%}

{%- elif phase_uuid == '92aed7aa-9d45-47f4-8a27-a1261e89aa5d' or phase_title == 'maintenance' -%}
  {# Maintenance is still active software unless the SMP explicitly says it will not be maintained. #}
  {%- set mg=h.val(replies,[id.ch_plan,id.q_maint])|trim -%}
  {%- set ml=h.answer_label(entities,mg)|trim -%}
  {%- set st.value='unsupported' if ml=='No' else 'active' -%}
{%- endif -%}

{%- if st.value -%}
