{# Split the SMP Keywords list into controlled EDAM topics and free-text keywords. #}
{% macro apply(ns, dc, entities, replies) -%}
{%- set kr=replies.get(([id.ch_general,id.q_keywords])|reply_path) -%}
{%- set items=kr.value if kr is not none else [] -%}
{%- set out=namespace(topics=[], keywords=[], topic_seen=[], keyword_seen=[]) -%}

{%- for it in items -%}
  {%- set r=replies.get(([id.ch_general,id.q_keywords,it,id.q_keyword])|reply_path) -%}
  {%- if r is not none -%}
    {%- set raw=r.raw if r.raw is defined else none -%}

    {# A genuine EDAM integration selection has structured raw data (label + iri).
       Custom replies do not, and remain public free-text keywords. #}
    {%- if raw is mapping and (raw.iri is defined or raw.label is defined) -%}
      {%- set t={} -%}
      {%- if raw.label is defined and raw.label|trim -%}
        {%- set t=dict(t,term=raw.label|safe|trim) -%}
      {%- endif -%}
      {%- if raw.iri is defined and raw.iri|trim -%}
        {%- set uri=h.edam_url(raw.iri)|trim -%}
        {%- set t=dict(t,uri=uri) -%}
      {%- endif -%}
      {%- set key=(t.uri|default('') ~ '|' ~ t.term|default('')) -%}
      {%- if t and key not in out.topic_seen -%}
        {%- set out.topics=out.topics+[t] -%}
        {%- set out.topic_seen=out.topic_seen+[key] -%}
      {%- endif -%}
    {%- else -%}
      {%- set value=r.value|default('',true)|safe|trim -%}
      {%- if value and value not in out.keyword_seen -%}
        {%- set out.keywords=out.keywords+[value] -%}
        {%- set out.keyword_seen=out.keyword_seen+[value] -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- if out.topics -%}
  {%- set ns.root=dict(ns.root,topics={'entries':out.topics}) -%}
{%- endif -%}
{%- if out.keywords -%}
  {%- set ns.root=dict(ns.root,keywords={'entries':out.keywords}) -%}
{%- endif -%}
{%- endmacro %}

