    {%- set raw=dr.raw if dr is not none and dr.raw is defined else none -%}
    {%- set dstr=dr.value|default('',true)|trim if dr is not none else '' -%}
    {%- set doi0=raw.DOI if raw is mapping and raw.DOI is defined else dstr -%}
    {%- set doi=h.doi_url(doi0)|trim -%}
    {%- set o={} -%}
    {%- if raw is mapping and raw.title is defined and raw.title %}{%- set o=dict(o,title=raw.title[0]) -%}{%- endif -%}
    {%- if raw is mapping and raw.type is defined and raw.type %}{%- set o=dict(o,type=raw.type) -%}{%- endif -%}
    {%- if doi %}{%- set o=dict(o,doi=doi,url=doi) -%}{%- endif -%}
    {%- set pmid=h.val(replies,[id.ch_lic,id.q_pubs,pubg,id.q_pub_list,it,id.q_pub_pmid])|trim -%}{%- if pmid %}{%- set o=dict(o,pmid=h.pmid_url(pmid)|trim) -%}{%- endif -%}
    {%- set pmcid=h.val(replies,[id.ch_lic,id.q_pubs,pubg,id.q_pub_list,it,id.q_pub_pmcid])|trim -%}{%- if pmcid %}{%- set o=dict(o,pmcid=h.pmcid_url(pmcid)|trim) -%}{%- endif -%}
    {%- set note=h.val(replies,[id.ch_lic,id.q_pubs,pubg,id.q_pub_list,it,id.q_pub_note])|trim -%}
    {%- set pv=h.val(replies,[id.ch_lic,id.q_pubs,pubg,id.q_pub_list,it,id.q_pub_ver])|trim -%}
    {%- if pv %}{%- set note=(note ~ '\n\n' if note else '') ~ 'Associated software version: ' ~ pv -%}{%- endif -%}
    {%- if note %}{%- set o=dict(o,note=note) -%}{%- endif -%}
    {%- if raw is mapping and raw.author is defined and raw.author -%}
      {%- set aus=namespace(items=[]) -%}
      {%- for a in raw.author -%}
        {%- set gn=a.given|default('')|trim -%}{%- set fn=a.family|default('')|trim -%}{%- set nm=(gn ~ ' ' ~ fn)|trim -%}
        {%- if nm -%}
          {%- set po={'name':nm} -%}{%- if gn %}{%- set po=dict(po,given_names=gn) -%}{%- endif -%}{%- if fn %}{%- set po=dict(po,family_names=fn) -%}{%- endif -%}
          {%- if a.ORCID is defined and a.ORCID %}{%- set po=dict(po,orcid=h.orcid_url(a.ORCID)|trim) -%}{%- endif -%}
          {%- if a.affiliation is defined and a.affiliation -%}{%- set afs=namespace(items=[]) -%}{%- for af in a.affiliation -%}{%- if af.name is defined and af.name %}{%- set afs.items=afs.items+[{'name':af.name}] -%}{%- endif -%}{%- endfor -%}{%- if afs.items %}{%- set po=dict(po,affiliations=afs.items) -%}{%- endif -%}{%- endif -%}
          {%- set aus.items=aus.items+[po] -%}
        {%- endif -%}
      {%- endfor -%}
      {%- if aus.items %}{%- set o=dict(o,authors=aus.items) -%}{%- endif -%}
    {%- endif -%}
    {%- if raw is mapping -%}
      {%- set cparts=namespace(items=[]) -%}
      {%- if raw.author is defined and raw.author -%}{%- set first=raw.author[0].family|default(raw.author[0].given|default('')) -%}{%- if first %}{%- set cparts.items=cparts.items+[first ~ (' et al.' if raw.author|length>1 else '')] -%}{%- endif -%}{%- endif -%}
      {%- if raw.published is defined and raw.published['date-parts'] is defined and raw.published['date-parts'] %}{%- set cparts.items=cparts.items+['(' ~ (raw.published['date-parts'][0][0]|string) ~ ').'] -%}{%- endif -%}
      {%- if raw.title is defined and raw.title %}{%- set cparts.items=cparts.items+[raw.title[0] ~ '.'] -%}{%- endif -%}
      {%- if raw['container-title'] is defined and raw['container-title'] %}{%- set cparts.items=cparts.items+[raw['container-title'][0] ~ '.'] -%}{%- endif -%}
      {%- if doi %}{%- set cparts.items=cparts.items+[doi] -%}{%- endif -%}
      {%- if cparts.items %}{%- set o=dict(o,citation=cparts.items|join(' ')) -%}{%- endif -%}
    {%- endif -%}
    {%- set o=dict(o,preferred=loop.first) -%}
    {%- if o|length > 1 %}{%- set pubs.items=pubs.items+[o] -%}{%- endif -%}
  {%- endfor -%}
  {%- if pubs.items %}{%- set ns.root=dict(ns.root,publications={'entries':pubs.items}) -%}{%- endif -%}
{%- endif -%}
{%- endmacro %}

