{# language-aware quality_tools and project_manager; first programming language preferred #}
{% macro apply(ns, dc, entities, replies) -%}
{%- set lgr=replies.get(([id.ch_int,id.q_langs])|reply_path) -%}
{%- set lits=lgr.value if lgr is not none else [] -%}
{%- set lang=namespace(first='') -%}
{%- for it in lits -%}
  {%- if loop.first -%}{%- set lang.first=it -%}{%- endif -%}
{%- endfor -%}

{# Quality tools. Use namespace because ordinary Jinja variables assigned
   inside loops do not persist outside the loop scope. #}
{%- set q=namespace(formatter='',linter='',checker='') -%}
{%- set qg=h.val(replies,[id.ch_test,id.q_quality])|trim -%}
{%- if h.answer_label(entities,qg)|trim=='Yes' -%}
  {%- set qr=replies.get(([id.ch_test,id.q_quality,qg,id.q_quality_list])|reply_path) -%}
  {%- set qits=qr.value if qr is not none else [] -%}

  {# Pass 1: tools explicitly associated with the first programming language.
     Pass 2: fallback to any recognized tool. #}
  {%- for pass_no in [1,2] -%}
    {%- for it in qits -%}
      {%- set slr=replies.get(([id.ch_test,id.q_quality,qg,id.q_quality_list,it,id.q_quality_lang])|reply_path) -%}
      {%- set sel=slr.value|default('',true)|trim if slr is not none else '' -%}
      {%- if (pass_no==1 and lang.first and sel==lang.first) or pass_no==2 -%}
        {%- set tool=h.val(replies,[id.ch_test,id.q_quality,qg,id.q_quality_list,it,id.q_quality_tool])|trim|lower -%}

        {%- if not q.formatter -%}
          {%- for pair in [('ruff','ruff'),('black','black'),('styler','styler'),('prettier','prettier'),('rustfmt','rustfmt'),('clang-format','clang-format')] -%}
            {%- if pair[0] in tool and not q.formatter -%}{%- set q.formatter=pair[1] -%}{%- endif -%}
          {%- endfor -%}
        {%- endif -%}

        {%- if not q.linter -%}
          {%- for pair in [('ruff','ruff'),('flake8','flake8'),('pylint','pylint'),('lintr','lintr'),('eslint','eslint'),('clippy','clippy'),('clang-tidy','clang-tidy')] -%}
            {%- if pair[0] in tool and not q.linter -%}{%- set q.linter=pair[1] -%}{%- endif -%}
          {%- endfor -%}
        {%- endif -%}

        {%- if not q.checker -%}
          {%- for pair in [('mypy','mypy'),('basedpyright','basedpyright'),('pyright','pyright'),('pyre','pyre'),('tsc','tsc'),('rustc','rustc'),('flow','Flow')] -%}
            {%- if pair[0] in tool and not q.checker -%}{%- set q.checker=pair[1] -%}{%- endif -%}
          {%- endfor -%}
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
{%- endif -%}

{%- set qo={} -%}
{%- if q.formatter %}{%- set qo=dict(qo,formatter=q.formatter) -%}{%- endif -%}
{%- if q.linter %}{%- set qo=dict(qo,linter=q.linter) -%}{%- endif -%}
{%- if q.checker %}{%- set qo=dict(qo,type_checker=q.checker) -%}{%- endif -%}
{%- if qo %}{%- set ns.root=dict(ns.root,quality_tools=qo) -%}{%- endif -%}

{# Project manager, using the same first-language preference. #}
{%- set pm=namespace(value='') -%}
{%- set mg=h.val(replies,[id.ch_test,id.q_manager])|trim -%}
{%- if h.answer_label(entities,mg)|trim=='Yes' -%}
  {%- set mr=replies.get(([id.ch_test,id.q_manager,mg,id.q_manager_list])|reply_path) -%}
  {%- set mits=mr.value if mr is not none else [] -%}
  {%- for pass_no in [1,2] -%}
    {%- for it in mits -%}
      {%- set slr=replies.get(([id.ch_test,id.q_manager,mg,id.q_manager_list,it,id.q_manager_lang])|reply_path) -%}
      {%- set sel=slr.value|default('',true)|trim if slr is not none else '' -%}
      {%- if not pm.value and ((pass_no==1 and lang.first and sel==lang.first) or pass_no==2) -%}
        {%- set tool=h.val(replies,[id.ch_test,id.q_manager,mg,id.q_manager_list,it,id.q_manager_tool])|trim|lower -%}
        {%- for x in ['uv','poetry','pdm','hatch','pixi','pip','renv','rix','cargo','npm','pnpm','yarn','maven','gradle','cmake'] -%}
          {%- if not pm.value and x in tool -%}{%- set pm.value=x -%}{%- endif -%}
        {%- endfor -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
{%- endif -%}
{%- if pm.value %}{%- set ns.root=dict(ns.root,project_manager=pm.value) -%}{%- endif -%}
{%- endmacro %}

