{%- if r is not none -%}
  {%- set raw=r.raw if r.raw is defined else none -%}
  {%- if raw is mapping and raw.label is defined and raw.label|trim -%}
    {%- set d=dict(d,term=raw.label|safe|trim) -%}
  {%- endif -%}
  {%- set raw_uri=raw.iri if raw is mapping and raw.iri is defined else r.value|default('',true)|safe|trim -%}
  {%- if raw_uri and (('://' in raw_uri) or raw_uri.startswith('EDAM:') or raw_uri.startswith('data_')) -%}
    {%- set d=dict(d,uri=h.edam_url(raw_uri)|trim) -%}
  {%- elif raw_uri and not d.term|default('') -%}
    {# EDAM Data integration allows custom replies. Preserve custom data text as term. #}
    {%- set d=dict(d,term=raw_uri) -%}
  {%- endif -%}
{%- endif -%}
{{- d|tojson -}}
{%- endmacro %}

{% macro apply(ns, dc, entities, replies) -%}
{%- set fr=replies.get(([id.ch_int,id.q_funcs])|reply_path) -%}
{%- set fits=fr.value if fr is not none else [] -%}
{%- set fns=namespace(items=[]) -%}

{%- for fit in fits -%}
  {%- set fo={} -%}

  {# Operations #}
  {%- set orr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_ops])|reply_path) -%}
  {%- set oits=orr.value if orr is not none else [] -%}
  {%- set ons=namespace(items=[]) -%}
  {%- for oit in oits -%}
    {%- set opr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_ops,oit,id.q_op])|reply_path) -%}
    {%- if opr is not none -%}
      {%- set raw=opr.raw if opr.raw is defined else none -%}
      {%- set oo={} -%}
      {%- if raw is mapping and raw.label is defined and raw.label|trim -%}
        {%- set oo=dict(oo,term=raw.label|safe|trim) -%}
      {%- endif -%}
      {%- set uri=raw.iri if raw is mapping and raw.iri is defined else opr.value|default('',true)|safe|trim -%}
      {%- if uri and (('://' in uri) or uri.startswith('EDAM:') or uri.startswith('operation_')) -%}
        {%- set oo=dict(oo,uri=h.edam_url(uri)|trim) -%}
      {%- elif uri and not oo.term|default('') -%}
        {%- set oo=dict(oo,term=uri) -%}
      {%- endif -%}
      {%- if oo %}{%- set ons.items=ons.items+[oo] -%}{%- endif -%}
    {%- endif -%}
  {%- endfor -%}
  {%- if ons.items %}{%- set fo=dict(fo,operations=ons.items) -%}{%- endif -%}

  {# Inputs: each list item is one function_io with optional data + many formats. #}
  {%- set inr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_inputs])|reply_path) -%}
  {%- set inits=inr.value if inr is not none else [] -%}
  {%- set inns=namespace(items=[]) -%}
  {%- for iit in inits -%}
    {%- set io={} -%}

    {%- set dr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_inputs,iit,id.q_input_data])|reply_path) -%}
    {%- if dr is not none -%}
      {%- set raw=dr.raw if dr.raw is defined else none -%}
      {%- set dobj={} -%}
      {%- if raw is mapping and raw.label is defined and raw.label|trim -%}
        {%- set dobj=dict(dobj,term=raw.label|safe|trim) -%}
      {%- endif -%}
      {%- set dv=raw.iri if raw is mapping and raw.iri is defined else dr.value|default('',true)|safe|trim -%}
      {%- if dv and (('://' in dv) or dv.startswith('EDAM:') or dv.startswith('data_')) -%}
        {%- set dobj=dict(dobj,uri=h.edam_url(dv)|trim) -%}
      {%- elif dv and not dobj.term|default('') -%}
        {%- set dobj=dict(dobj,term=dv) -%}
      {%- endif -%}
      {%- if dobj %}{%- set io=dict(io,data=dobj) -%}{%- endif -%}
    {%- endif -%}

    {%- set lr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_inputs,iit,id.q_infmts])|reply_path) -%}
    {%- set lits=lr.value if lr is not none else [] -%}
    {%- set fmts=namespace(items=[]) -%}
    {%- for lit in lits -%}
      {%- set sr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_inputs,iit,id.q_infmts,lit,id.q_infmt])|reply_path) -%}
      {%- set df=sr.value|default('',true)|trim if sr is not none else '' -%}
      {%- if df -%}
        {# Inline format construction to keep values as objects, not rendered JSON strings. #}
        {%- set d={} -%}
        {%- set nr=replies.get(([id.ch_int,id.q_formats,df,id.q_fmt_name])|reply_path) -%}
        {%- if nr is not none -%}
          {%- set raw=nr.raw if nr.raw is defined else none -%}
          {%- if raw is mapping and raw.label is defined and raw.label|trim -%}{%- set d=dict(d,term=raw.label|safe|trim) -%}{%- endif -%}
          {%- set uv=raw.iri if raw is mapping and raw.iri is defined else nr.value|default('',true)|safe|trim -%}
          {%- if uv and (('://' in uv) or uv.startswith('EDAM:') or uv.startswith('format_')) -%}{%- set d=dict(d,uri=h.edam_url(uv)|trim) -%}
          {%- elif uv and not d.term|default('') -%}{%- set d=dict(d,term=uv) -%}{%- endif -%}
        {%- endif -%}
        {%- set vv=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_ver])|trim -%}
        {%- set ss=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_schema])|trim -%}
        {%- set sm=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_sample])|trim -%}
        {%- if vv %}{%- set d=dict(d,version_constraint=vv) -%}{%- endif -%}
        {%- if ss %}{%- set d=dict(d,schema_constraints=ss) -%}{%- endif -%}
        {%- if sm %}{%- set d=dict(d,sample_url=sm) -%}{%- endif -%}
        {%- if d %}{%- set fmts.items=fmts.items+[d] -%}{%- endif -%}
      {%- endif -%}
    {%- endfor -%}
    {%- if fmts.items %}{%- set io=dict(io,format=fmts.items) -%}{%- endif -%}

    {%- if io %}{%- set inns.items=inns.items+[io] -%}{%- endif -%}
  {%- endfor -%}
  {%- if inns.items %}{%- set fo=dict(fo,inputs=inns.items) -%}{%- endif -%}

  {# Outputs #}
  {%- set outr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_outputs])|reply_path) -%}
  {%- set outits=outr.value if outr is not none else [] -%}
  {%- set outns=namespace(items=[]) -%}
  {%- for oit in outits -%}
    {%- set io={} -%}

    {%- set dr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_outputs,oit,id.q_output_data])|reply_path) -%}
    {%- if dr is not none -%}
      {%- set raw=dr.raw if dr.raw is defined else none -%}
      {%- set dobj={} -%}
      {%- if raw is mapping and raw.label is defined and raw.label|trim -%}{%- set dobj=dict(dobj,term=raw.label|safe|trim) -%}{%- endif -%}
      {%- set dv=raw.iri if raw is mapping and raw.iri is defined else dr.value|default('',true)|safe|trim -%}
      {%- if dv and (('://' in dv) or dv.startswith('EDAM:') or dv.startswith('data_')) -%}{%- set dobj=dict(dobj,uri=h.edam_url(dv)|trim) -%}
      {%- elif dv and not dobj.term|default('') -%}{%- set dobj=dict(dobj,term=dv) -%}{%- endif -%}
      {%- if dobj %}{%- set io=dict(io,data=dobj) -%}{%- endif -%}
    {%- endif -%}

    {%- set lr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_outputs,oit,id.q_outfmts])|reply_path) -%}
    {%- set lits=lr.value if lr is not none else [] -%}
    {%- set fmts=namespace(items=[]) -%}
    {%- for lit in lits -%}
      {%- set sr=replies.get(([id.ch_int,id.q_funcs,fit,id.q_outputs,oit,id.q_outfmts,lit,id.q_outfmt])|reply_path) -%}
      {%- set df=sr.value|default('',true)|trim if sr is not none else '' -%}
      {%- if df -%}
        {%- set d={} -%}
        {%- set nr=replies.get(([id.ch_int,id.q_formats,df,id.q_fmt_name])|reply_path) -%}
        {%- if nr is not none -%}
          {%- set raw=nr.raw if nr.raw is defined else none -%}
          {%- if raw is mapping and raw.label is defined and raw.label|trim -%}{%- set d=dict(d,term=raw.label|safe|trim) -%}{%- endif -%}
          {%- set uv=raw.iri if raw is mapping and raw.iri is defined else nr.value|default('',true)|safe|trim -%}
          {%- if uv and (('://' in uv) or uv.startswith('EDAM:') or uv.startswith('format_')) -%}{%- set d=dict(d,uri=h.edam_url(uv)|trim) -%}
          {%- elif uv and not d.term|default('') -%}{%- set d=dict(d,term=uv) -%}{%- endif -%}
        {%- endif -%}
        {%- set vv=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_ver])|trim -%}
        {%- set ss=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_schema])|trim -%}
        {%- set sm=h.val(replies,[id.ch_int,id.q_formats,df,id.q_fmt_sample])|trim -%}
        {%- if vv %}{%- set d=dict(d,version_constraint=vv) -%}{%- endif -%}
        {%- if ss %}{%- set d=dict(d,schema_constraints=ss) -%}{%- endif -%}
        {%- if sm %}{%- set d=dict(d,sample_url=sm) -%}{%- endif -%}
        {%- if d %}{%- set fmts.items=fmts.items+[d] -%}{%- endif -%}
      {%- endif -%}
    {%- endfor -%}
    {%- if fmts.items %}{%- set io=dict(io,format=fmts.items) -%}{%- endif -%}

    {%- if io %}{%- set outns.items=outns.items+[io] -%}{%- endif -%}
  {%- endfor -%}
  {%- if outns.items %}{%- set fo=dict(fo,outputs=outns.items) -%}{%- endif -%}

  {%- set cmd=h.val(replies,[id.ch_int,id.q_funcs,fit,id.q_cmd])|trim -%}
  {%- if cmd %}{%- set fo=dict(fo,cmd=cmd) -%}{%- endif -%}
  {%- set note=h.val(replies,[id.ch_int,id.q_funcs,fit,id.q_func_note])|trim -%}
  {%- if note %}{%- set fo=dict(fo,note=note) -%}{%- endif -%}

  {%- if fo %}{%- set fns.items=fns.items+[fo] -%}{%- endif -%}
{%- endfor -%}

{%- if fns.items -%}
  {%- set ns.root=dict(ns.root,software_functions={'entries':fns.items}) -%}
{%- endif -%}
{%- endmacro %}

