{%- set ug=h.val(replies,[id.ch_docs,id.q_udocs])|trim -%}{%- set ul=h.answer_label(entities,ug)|trim -%}
{%- set dg=h.val(replies,[id.ch_docs,id.q_ddocs])|trim -%}{%- set dl=h.answer_label(entities,dg)|trim -%}
{%- set depg=h.val(replies,[id.ch_docs,id.q_depdocs])|trim -%}{%- set depl=h.answer_label(entities,depg)|trim -%}
{%- set docurl='' -%}
{%- if ul=='Yes - full doc' %}{%- set docurl=h.val(replies,[id.ch_docs,id.q_udocs,ug,id.q_udoc_url])|trim -%}{%- endif -%}
{%- if not docurl and dl=='Yes' %}{%- set docurl=h.val(replies,[id.ch_docs,id.q_ddocs,dg,id.q_ddoc_url])|trim -%}{%- endif -%}
{%- if not docurl and dl=='Yes' %}{%- set docurl=h.val(replies,[id.ch_docs,id.q_ddocs,dg,id.q_api_url])|trim -%}{%- endif -%}
{%- if not docurl and depl=='Yes' %}{%- set docurl=h.val(replies,[id.ch_docs,id.q_depdocs,depg,id.q_depdoc_url])|trim -%}{%- endif -%}
{%- if docurl %}{%- set urls=dict(urls,documentation=docurl) -%}{%- endif -%}
{%- if urls %}{%- set ns.root=dict(ns.root,urls=urls) -%}{%- endif -%}
{%- endmacro %}

